#include <iostream>
using namespace std;

class Employee
{
public:
  Employee(int id)
  {
    this->id = id;
  }

  ~Employee()
  {
    cout << "object with id " << id << " is destroyed" << endl;
  }

private:
  int id;
};

int main()
{
  Employee* e1 = new Employee(1);
  Employee* e2 = new Employee(2);
  Employee* e3 = new Employee(3);

  delete e3;
  delete e2;
  delete e1;

  return 0;
}

