#include <iostream>

class Circle {
public:
    Circle() : radius(1.0) {}
    explicit Circle(double radius) {
        // Disambiguate member from shadowed parameter
        this->radius = (radius >= 0.0) ? radius : 0.0;
    }

    double getRadius() const {
        return this->radius;
    }

    void setRadius(double radius) {
        this->radius = (radius >= 0.0) ? radius : 0.0;
    }

    double getArea() const {
        return radius * radius * 3.14159;
    }

private:
    double radius;
};

int main() {
    Circle c1(5.0);
    std::cout << "c1 initial radius: " << c1.getRadius() << "\n";
    c1.setRadius(7.5);
    std::cout << "c1 updated radius: " << c1.getRadius() << "\n";
    std::cout << "c1 area: " << c1.getArea() << "\n";
    return 0;
}

#include <iostream>

class Circle {
public:
    Circle() : radius(1.0) {
        ++numberOfObjects;
    }
    explicit Circle(double r) : radius(r >= 0 ? r : 0) {
        ++numberOfObjects;
    }
    ~Circle() {
        --numberOfObjects;
    }

    static int getNumberOfObjects() {
        return numberOfObjects;
    }

private:
    double radius;
    static int numberOfObjects;
};

int Circle::numberOfObjects = 0;

int main() {
    Circle* p1 = new Circle();
    Circle* p2 = new Circle(2.5);
    Circle* p3 = new Circle(4.0);

    std::cout << "Number of circle objects created: " << Circle::getNumberOfObjects() << "\n";

    delete p1;
    p1 = nullptr;

    std::cout << "Number of circle objects remaining: " << Circle::getNumberOfObjects() << "\n";

    delete p2;
    delete p3;
    p2 = nullptr;
    p3 = nullptr;

    std::cout << "Final object count: " << Circle::getNumberOfObjects() << "\n";
    return 0;
}
